#include <bits/stdc++.h>
using namespace std;

const int N = 100010;
const long long MOD = 1000000007;

int parent_[N], sz[N];
int edgeCount[N], vertexCount[N];

int findRoot(int x) {
    return parent_[x] == x ? x : parent_[x] = findRoot(parent_[x]);
}

void unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return;
    if (sz[a] < sz[b]) swap(a, b);
    parent_[b] = a;
    sz[a] += sz[b];
}

long long qpow(long long a, int b) {
    long long result = 1;
    while (b > 0) {
        if (b & 1) result = result * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return result;
}

int main() {
    int n;
    scanf("%d", &n);

    map<int, int> xRepresentative, yRepresentative;

    for (int i = 1; i <= n; ++i) {
        parent_[i] = i;
        sz[i] = 1;
    }

    for (int i = 1; i <= n; ++i) {
        int x, y;
        scanf("%d%d", &x, &y);

        auto itX = xRepresentative.find(x);
        if (itX != xRepresentative.end())
            unite(i, itX->second);
        else
            xRepresentative[x] = i;

        auto itY = yRepresentative.find(y);
        if (itY != yRepresentative.end())
            unite(i, itY->second);
        else
            yRepresentative[y] = i;
    }

    for (int i = 1; i <= n; ++i)
        ++edgeCount[findRoot(i)];

    for (const auto& [coordinate, point] : xRepresentative)
        ++vertexCount[findRoot(point)];

    for (const auto& [coordinate, point] : yRepresentative)
        ++vertexCount[findRoot(point)];

    long long answer = 1;
    for (int i = 1; i <= n; ++i) {
        if (findRoot(i) != i) continue;

        long long ways = qpow(2, vertexCount[i]);
        if (edgeCount[i] + 1 == vertexCount[i])
            ways = (ways - 1 + MOD) % MOD;

        answer = answer * ways % MOD;
    }

    printf("%lld\n", answer);
    return 0;
}

